function Ref([string]$f){$i=Get-Item $f;if($i.Length -gt 4MB -or ($i.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Count1 reference bound'};return @{path=$f;sha256=('sha256:'+(Get-FileHash $f).Hash.ToLowerInvariant());bytes=$i.Length}}
