$obsPath=Join-Path $run 'native-observation.json';$obs=@(Get-Content -Raw $obsPath|ConvertFrom-Json)
if($release.lockReleased -ne $true -or $release.wholeBatchExitConfirmed -ne $true -or $release.sourceInputsHash -cne $c.sourceInputsHash -or $release.issuedMetadataHash -cne $c.issuedMetadataHash -or $t.memoryReceipt.status -cne 'passed' -or $t.memoryReceipt.activeProcessCount -ne 1 -or $obs.Count -ne 1 -or $obs[0].hostValid -ne $true -or $obs[0].probeForegroundAtCapture -ne $false -or $obs[0].backgroundPlacementRequested -ne $true){throw 'Count1 actual observation closure rejected'}
$proof=Join-Path $admission 'count1-proof.json';if(Test-Path $proof){throw 'fresh Count1 derived proof required'}
@{kind='factory-rectangle-count1-proof-v1';status='completed-source-bound-observation';count=1;caseID=$si.caseID;caseHash=$si.caseHash;tupleID=$si.tupleID;sourceHash=$si.sourceHash;planHash=$si.planHash;compileReceiptHash=$si.compileReceiptHash;exeHash=$si.exeHash;runtimeSourceCommit=$si.runtimeSourceCommit;rendererSha256=$si.rendererSha256;serializerControlSha256=$si.serializerControlSha256;runRoot=$run;owner=$c.owner;issuedMetadataHash=$c.issuedMetadataHash;sourceInputsHash=$c.sourceInputsHash;native=@{firstCaptureProof=$true;backgroundWindow=$true;retainedRendererHandle=$true;workerTerminalProof=$true;rendererTerminalProof=$true;streamsSealed=$true;jobMemoryBound=$true;lockReleased=$true;activeProcessCount=$t.memoryReceipt.activeProcessCount;peakJobMemoryUsedBytes=$t.memoryReceipt.peakJobMemoryUsedBytes};refs=@{observation=(Ref $obsPath);release=(Ref $releasePath);task=(Ref (Join-Path $control 'task-result.json'));coordinator=(Ref (Join-Path $control 'coordinator.json'));renderer=(Ref (Join-Path $run 'native-01\final-exit-certificate.json'));worker=(Ref (Join-Path $run 'native-01\uia-worker\final-exit-certificate.json'))};qualified=$false;parity='held'}|ConvertTo-Json -Depth 16|Set-Content $proof -Encoding UTF8
Add-Type -AssemblyName System.IO.Compression
$zip='D:\Claude\swiftright\.factory-work\hosts\rectangle\export-count1-r3-r1.zip';if(Test-Path $zip){throw 'fresh export required'}
$files=@();$total=0
foreach($group in @(@{name='native';root=$run},@{name='control';root=$control},@{name='admission';root=$admission})){
 foreach($f in Get-ChildItem -LiteralPath $group.root -Recurse -File){if(($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $f.Length -gt 4MB){throw 'export file bound'};$total+=$f.Length;if($files.Count -ge 128 -or $total -gt 12MB){throw 'explicit Count1 export bound'};$rel=$group.name+'/'+$f.FullName.Substring($group.root.Length+1).Replace('\','/');$files+=@{path=$rel;originalPath=$f.FullName;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLowerInvariant()}}
}
$manifest=Join-Path $control 'export-manifest.json';@{kind='root-rectangle-count1-export-v1';files=$files;totalBytes=$total;count=$files.Count;count1Proof=(Ref $proof)}|ConvertTo-Json -Depth 12|Set-Content $manifest -Encoding UTF8
$stream=[IO.File]::Open($zip,[IO.FileMode]::CreateNew);$a=[IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Create,$false)
try{foreach($row in $files){$entry=$a.CreateEntry($row.path);$target=$entry.Open();$source=[IO.File]::OpenRead($row.originalPath);try{$source.CopyTo($target,1048576)}finally{$source.Dispose();$target.Dispose()}};$e=$a.CreateEntry('export-manifest.json');$o=$e.Open();$i=[IO.File]::OpenRead($manifest);try{$i.CopyTo($o,1048576)}finally{$i.Dispose();$o.Dispose()}}finally{$a.Dispose();$stream.Dispose()}
@{status='Count1-proof-exported';zipPath=$zip;zipBytes=(Get-Item $zip).Length;zipSha256=(Get-FileHash $zip).Hash.ToLowerInvariant();proofHash=(Get-FileHash $proof).Hash.ToLowerInvariant();files=$files.Count;bytes=$total;lock=(Get-Content -Raw 'D:\Claude\desktop.lock').Trim()}|ConvertTo-Json
